  j constant jsonb := $j$[
{"id":"bd87bb00-5110-4b2d-bd35-0aebf3a99fb9","recipe_group_id":"2b7dedcb-61b3-4b53-9373-d430aeca9dd5","language":"es","slug":"asado-de-res-al-horno","public_path":"/asado-de-res-al-horno","source_url":null,"title":"Asado de res al horno","excerpt":"Asado de res al horno con papas y zanahorias: una pieza entera sellada, sazonada con ajo y hierbas, asada sobre las verduras y cortada en lonchas. Para 6 porciones.","summary":"Este asado de res al horno se hace con una pieza entera de cuadril o posta, atada y frotada con ajo, romero, tomillo, sal y pimienta. Se sella en la sartén para dorarla y se asa en el horno sobre una cama de papas, zanahorias y cebolla, que se cocinan con los jugos de la carne.\n\nLleva 20 minutos de preparación, 30 de atemperado, 80 de cocción y 15 de reposo. Rinde 6 porciones.","category":"Platos principales","difficulty":"Media","course":"Plato principal","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":80,"total_time_minutes":145,"servings":6,"keywords":["asado de res al horno","receta de asado de res","asado de res con papas y zanahorias","cómo hacer asado de res al horno","carne asada al horno","cuadril al horno","asado de carne con verduras"],"ingredients":[{"name":"pieza de res (cuadril o posta), atada","amount":"1200","unit":"g","group":"Para la carne"},{"name":"dientes de ajo","amount":"4","unit":"","group":"Para la carne"},{"name":"ramitas de romero","amount":"2","unit":"","group":"Para la carne"},{"name":"ramitas de tomillo","amount":"4","unit":"","group":"Para la carne"},{"name":"sal","amount":"1 1/2","unit":"cucharadita","group":"Para la carne"},{"name":"pimienta negra","amount":"1","unit":"cucharadita","group":"Para la carne"},{"name":"aceite de oliva","amount":"1","unit":"cucharada","group":"Para la carne"},{"name":"papas","amount":"800","unit":"g","group":"Para las verduras"},{"name":"zanahorias","amount":"400","unit":"g","group":"Para las verduras"},{"name":"cebollas","amount":"2","unit":"","group":"Para las verduras"},{"name":"aceite de oliva","amount":"2","unit":"cucharada","group":"Para las verduras"},{"name":"sal","amount":"1/2","unit":"cucharadita","group":"Para las verduras"}],"steps":[{"title":"Prepara los ingredientes","content":"Ten a mano 1,2 kg de res en una pieza (cuadril o posta) atada con hilo de cocina, 800 g de papas, 400 g de zanahorias, 2 cebollas, 4 dientes de ajo, romero, tomillo, aceite de oliva, sal y pimienta. Saca la carne de la nevera y precalienta el horno a 180 °C.","image_url":"/recetas/asado-de-res-al-horno/paso-01.webp","image_alt":"Asado de res al horno: Prepara los ingredientes"},{"title":"Sazona la carne","content":"Seca la pieza con papel de cocina. Mezcla 1 y ½ cucharaditas de sal, 1 cucharadita de pimienta, 4 dientes de ajo picados y las hojas picadas de 2 ramitas de romero y 4 de tomillo, y frota toda la carne. Déjala 30 minutos a temperatura ambiente.","image_url":"/recetas/asado-de-res-al-horno/paso-02.webp","image_alt":"Asado de res al horno: Sazona la carne"},{"title":"Sella la carne","content":"Calienta 1 cucharada de aceite en una sartén de hierro a fuego alto. Sella la pieza de 2 a 3 minutos por cada lado, incluidos los extremos, hasta que esté dorada por todas partes, unos 10 minutos en total.","image_url":"/recetas/asado-de-res-al-horno/paso-03.webp","image_alt":"Asado de res al horno: Sella la carne"},{"title":"Prepara las verduras","content":"Corta 800 g de papa y 400 g de zanahoria en trozos de 4 cm y las 2 cebollas en gajos. Mézclalos en una fuente de horno con 2 cucharadas de aceite y ½ cucharadita de sal. Pon la carne sellada en el centro, sobre las verduras.","image_url":"/recetas/asado-de-res-al-horno/paso-04.webp","image_alt":"Asado de res al horno: Prepara las verduras"},{"title":"Hornea el asado","content":"Hornea a 180 °C, en el nivel medio, de 60 a 70 minutos. A la mitad del tiempo, remueve las verduras para que se doren por igual.","image_url":"/recetas/asado-de-res-al-horno/paso-05.webp","image_alt":"Asado de res al horno: Hornea el asado"},{"title":"Comprueba la temperatura","content":"Clava un termómetro de cocina en el centro de la carne. Retírala del horno a 58 °C para término medio, porque sube a unos 63 °C al reposar. Si aún no llega, hornéala 10 minutos más y vuelve a medir.","image_url":"/recetas/asado-de-res-al-horno/paso-06.webp","image_alt":"Asado de res al horno: Comprueba la temperatura"},{"title":"Deja reposar la carne","content":"Pasa la carne a una tabla, cúbrela sin apretar con papel de aluminio y déjala reposar 15 minutos para que no suelte los jugos al cortarla. Deja las verduras en la fuente.","image_url":"/recetas/asado-de-res-al-horno/paso-07.webp","image_alt":"Asado de res al horno: Deja reposar la carne"},{"title":"Corta y sirve","content":"Retira el hilo y corta la carne en lonchas de 1 cm, en contra de la fibra. Sírvela caliente con las papas, las zanahorias y los jugos que quedaron en la fuente.","image_url":"/recetas/asado-de-res-al-horno/paso-08.webp","image_alt":"Asado de res al horno: Corta y sirve"}],"image_url":"/recetas/asado-de-res-al-horno/portada.webp","gallery":[{"url":"/recetas/asado-de-res-al-horno/portada.webp","alt":"Asado de res al horno"}],"notes":"Corta siempre en contra de la fibra: así la carne queda más tierna. El tiempo depende del grosor de la pieza y del horno, por eso conviene usar un termómetro. Como referencia, 58 °C da un término medio rosado, y 65 °C o más un término más cocido. Si la pieza es más gruesa o más pesada, alarga el horneado. Los jugos de la fuente se pueden verter sobre las lonchas al servir. Las sobras se conservan 3 días en la nevera, bien tapadas; recaliéntalas con un poco de agua o caldo para que no se resequen.","nutrition":{"calories":570,"protein_g":44.6,"carbs_g":33,"fat_g":28.6,"sodium_mg":942,"serving_size":"1 porción (unos 150 g de carne y 200 g de verduras)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 6 porciones: 1.200 g de res cruda (aproximada con valores orientativos de cuadril sin FDC id; se cuenta toda aunque parte de la grasa y los jugos queden en la fuente), 800 g de papa, 400 g de zanahoria, 300 g de cebolla, 12 g de ajo, 3 g de romero, 3 g de tomillo, 40,5 g de aceite de oliva, 12 g de sal y 2,3 g de pimienta, todo contado aunque no se consuma por completo.","note":"Estimación por porción. La carne cruda pierde peso al asarse y los jugos de la fuente no se cuentan aparte, así que el consumo real puede variar.","inputs":[{"fdc_id":null,"description":"Beef, sirloin / rump, raw, lean and fat (proxy del cuadril o la posta; 1,2 kg crudos; valores aproximados)","grams":1200,"per100":{"calories":183,"protein_g":20.5,"carbs_g":0,"fat_g":10.7,"saturated_fat_g":4.2,"fiber_g":0,"sodium_mg":55}},{"fdc_id":"170026","description":"Potatoes, white, flesh and skin, raw (800 g)","grams":800,"per100":{"calories":69,"protein_g":1.68,"carbs_g":15.71,"fat_g":0.1,"saturated_fat_g":0.026,"fiber_g":2.4,"sodium_mg":6}},{"fdc_id":"170393","description":"Carrots, raw (400 g)","grams":400,"per100":{"calories":41,"protein_g":0.93,"carbs_g":9.58,"fat_g":0.24,"saturated_fat_g":0.037,"fiber_g":2.8,"sodium_mg":69}},{"fdc_id":"170000","description":"Onions, raw (2 cebollas medianas ≈ 300 g)","grams":300,"per100":{"calories":40,"protein_g":1.1,"carbs_g":9.34,"fat_g":0.1,"saturated_fat_g":0.042,"fiber_g":1.7,"sodium_mg":4}},{"fdc_id":"169230","description":"Garlic, raw (4 dientes ≈ 12 g)","grams":12,"per100":{"calories":149,"protein_g":6.36,"carbs_g":33.06,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17}},{"fdc_id":"173473","description":"Rosemary, fresh (2 ramitas, hojas ≈ 3 g)","grams":3,"per100":{"calories":131,"protein_g":3.31,"carbs_g":20.7,"fat_g":5.86,"saturated_fat_g":2.838,"fiber_g":14.1,"sodium_mg":26}},{"fdc_id":"173470","description":"Thyme, fresh (4 ramitas, hojas ≈ 3 g)","grams":3,"per100":{"calories":101,"protein_g":5.56,"carbs_g":24.45,"fat_g":1.68,"saturated_fat_g":0.467,"fiber_g":14,"sodium_mg":9}},{"fdc_id":"171413","description":"Oil, olive, salad or cooking (3 cucharadas ≈ 40,5 g; se cuenta todo)","grams":40.5,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0,"sodium_mg":2}},{"fdc_id":"173468","description":"Salt, table (1½ cucharaditas de la carne + ½ de las verduras ≈ 12 g; se cuenta toda)","grams":12,"per100":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":38758}},{"fdc_id":"170931","description":"Spices, pepper, black (1 cucharadita ≈ 2,3 g)","grams":2.3,"per100":{"calories":251,"protein_g":10.39,"carbs_g":63.95,"fat_g":3.26,"saturated_fat_g":1.392,"fiber_g":25.3,"sodium_mg":20}}]},"seo":{"title":"Asado de res al horno con papas y zanahorias | Manual de Cocina","description":"Asado de res al horno: pieza entera sellada, sazonada con ajo y hierbas y asada sobre papas y zanahorias. Para 6 porciones. Paso a paso con fotos.","image_variants":["/recetas/asado-de-res-al-horno/portada-1x1.webp","/recetas/asado-de-res-al-horno/portada-4x3.webp","/recetas/asado-de-res-al-horno/portada-16x9.webp"],"faq":[{"q":"¿Cuánto tiempo se asa la carne en el horno?","a":"Una pieza de 1,2 kg tarda de 60 a 70 minutos a 180 °C para un término medio. Lo más fiable es medir la temperatura del centro: 58 °C antes de reposar."},{"q":"¿Por qué hay que dejar reposar el asado?","a":"Durante el reposo los jugos se reparten por la pieza. Si la cortas enseguida, se escapan y la carne queda más seca."},{"q":"¿Qué corte de res se usa para un asado al horno?","a":"El cuadril o la posta funcionan bien porque son piezas magras que se cortan en lonchas. También sirve el lomo, que es más tierno pero más caro."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"959b6a89-b35e-5f1a-a150-93c757c2c37b","recipe_group_id":"2b7dedcb-61b3-4b53-9373-d430aeca9dd5","language":"de","slug":"rinderbraten-aus-dem-ofen","public_path":"/de/rinderbraten-aus-dem-ofen","source_url":null,"title":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten","excerpt":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten: ein ganzes Stück, angebraten, mit Knoblauch und Kräutern gewürzt, auf dem Gemüse gegart und in Scheiben geschnitten. 6 Portionen.","summary":"Für diesen Rinderbraten aus dem Ofen wird ein ganzes Stück Rinderhüfte oder Schwanzstück mit Küchengarn gebunden und mit Knoblauch, Rosmarin, Thymian, Salz und Pfeffer eingerieben. Es wird in der Pfanne angebraten und im Ofen auf einem Bett aus Kartoffeln, Karotten und Zwiebeln gegart, die im Bratensaft mitgaren.\n\nEr braucht 20 Minuten Vorbereitung, 30 Minuten zum Temperieren, 80 Minuten Garzeit und 15 Minuten Ruhezeit. Ergibt 6 Portionen.","category":"Hauptgerichte","difficulty":"Mittel","course":"Hauptgericht","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":80,"total_time_minutes":145,"servings":6,"keywords":["Rinderbraten aus dem Ofen","Rinderbraten Rezept","Rinderbraten mit Kartoffeln und Karotten","Rinderbraten im Ofen garen","Braten mit Ofengemüse","Rinderhüfte aus dem Ofen","Fleisch mit Gemüse aus dem Ofen"],"ingredients":[{"name":"Rindfleisch am Stück (Hüfte oder Schwanzstück), gebunden","amount":"1200","unit":"g","group":"Für das Fleisch"},{"name":"Knoblauchzehen","amount":"4","unit":"","group":"Für das Fleisch"},{"name":"Zweige Rosmarin","amount":"2","unit":"","group":"Für das Fleisch"},{"name":"Zweige Thymian","amount":"4","unit":"","group":"Für das Fleisch"},{"name":"Salz","amount":"1 1/2","unit":"Teelöffel","group":"Für das Fleisch"},{"name":"schwarzer Pfeffer","amount":"1","unit":"Teelöffel","group":"Für das Fleisch"},{"name":"Olivenöl","amount":"1","unit":"Esslöffel","group":"Für das Fleisch"},{"name":"Kartoffeln","amount":"800","unit":"g","group":"Für das Gemüse"},{"name":"Karotten","amount":"400","unit":"g","group":"Für das Gemüse"},{"name":"Zwiebeln","amount":"2","unit":"","group":"Für das Gemüse"},{"name":"Olivenöl","amount":"2","unit":"Esslöffel","group":"Für das Gemüse"},{"name":"Salz","amount":"1/2","unit":"Teelöffel","group":"Für das Gemüse"}],"steps":[{"title":"Zutaten vorbereiten","content":"1,2 kg Rindfleisch am Stück (Hüfte oder Schwanzstück) mit Küchengarn gebunden, 800 g Kartoffeln, 400 g Karotten, 2 Zwiebeln, 4 Knoblauchzehen, Rosmarin, Thymian, Olivenöl, Salz und Pfeffer bereitstellen. Das Fleisch aus dem Kühlschrank nehmen und den Backofen auf 180 °C vorheizen.","image_url":"/recetas/asado-de-res-al-horno/paso-01.webp","image_alt":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten: Zutaten vorbereiten"},{"title":"Fleisch würzen","content":"Das Fleisch mit Küchenpapier trocken tupfen. 1 ½ Teelöffel Salz, 1 Teelöffel Pfeffer, 4 gehackte Knoblauchzehen sowie die gehackten Blätter von 2 Zweigen Rosmarin und 4 Zweigen Thymian mischen und das ganze Fleisch damit einreiben. 30 Minuten bei Raumtemperatur ruhen lassen.","image_url":"/recetas/asado-de-res-al-horno/paso-02.webp","image_alt":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten: Fleisch würzen"},{"title":"Fleisch anbraten","content":"1 Esslöffel Öl in einer gusseisernen Pfanne bei hoher Hitze erhitzen. Das Fleisch auf jeder Seite 2 bis 3 Minuten anbraten, auch an den Enden, bis es rundum gebräunt ist, insgesamt etwa 10 Minuten.","image_url":"/recetas/asado-de-res-al-horno/paso-03.webp","image_alt":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten: Fleisch anbraten"},{"title":"Gemüse vorbereiten","content":"800 g Kartoffeln und 400 g Karotten in 4-cm-Stücke und die 2 Zwiebeln in Spalten schneiden. In einer Auflaufform mit 2 Esslöffeln Öl und ½ Teelöffel Salz mischen. Das angebratene Fleisch in die Mitte auf das Gemüse legen.","image_url":"/recetas/asado-de-res-al-horno/paso-04.webp","image_alt":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten: Gemüse vorbereiten"},{"title":"Braten im Ofen garen","content":"Bei 180 °C auf mittlerer Schiene 60 bis 70 Minuten garen. Nach der Hälfte der Zeit das Gemüse wenden, damit es gleichmäßig bräunt.","image_url":"/recetas/asado-de-res-al-horno/paso-05.webp","image_alt":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten: Braten im Ofen garen"},{"title":"Temperatur prüfen","content":"Ein Fleischthermometer in die Mitte des Fleisches stecken. Für Medium bei 58 °C aus dem Ofen nehmen, denn die Temperatur steigt beim Ruhen auf etwa 63 °C. Ist sie noch nicht erreicht, 10 Minuten länger garen und erneut messen.","image_url":"/recetas/asado-de-res-al-horno/paso-06.webp","image_alt":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten: Temperatur prüfen"},{"title":"Fleisch ruhen lassen","content":"Das Fleisch auf ein Brett legen, locker mit Alufolie abdecken und 15 Minuten ruhen lassen, damit beim Schneiden kein Saft ausläuft. Das Gemüse in der Form lassen.","image_url":"/recetas/asado-de-res-al-horno/paso-07.webp","image_alt":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten: Fleisch ruhen lassen"},{"title":"Aufschneiden und servieren","content":"Das Garn entfernen und das Fleisch quer zur Faser in 1 cm dicke Scheiben schneiden. Heiß mit Kartoffeln, Karotten und dem Bratensaft aus der Form servieren.","image_url":"/recetas/asado-de-res-al-horno/paso-08.webp","image_alt":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten: Aufschneiden und servieren"}],"image_url":"/recetas/asado-de-res-al-horno/portada.webp","gallery":[{"url":"/recetas/asado-de-res-al-horno/portada.webp","alt":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten"}],"notes":"Immer quer zur Faser schneiden: So wird das Fleisch zarter. Die Garzeit hängt von Dicke und Ofen ab, deshalb lohnt sich ein Thermometer. Als Anhaltspunkt: 58 °C ergeben ein rosafarbenes Medium, ab 65 °C ist es durchgegarter. Bei einem dickeren oder schwereren Stück die Garzeit verlängern. Den Bratensaft aus der Form beim Servieren über die Scheiben geben. Reste halten sich gut abgedeckt 3 Tage im Kühlschrank; mit etwas Wasser oder Brühe erwärmen, damit sie nicht austrocknen.","nutrition":{"calories":570,"protein_g":44.6,"carbs_g":33,"fat_g":28.6,"sodium_mg":942,"serving_size":"1 Portion (etwa 150 g Fleisch und 200 g Gemüse)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 6 Portionen geteilt: 1.200 g rohes Rindfleisch (mit Richtwerten für Hüfte ohne FDC-ID angenähert; alles gezählt, auch wenn ein Teil des Fetts und des Safts in der Form bleibt), 800 g Kartoffeln, 400 g Karotten, 300 g Zwiebeln, 12 g Knoblauch, 3 g Rosmarin, 3 g Thymian, 40,5 g Olivenöl, 12 g Salz und 2,3 g Pfeffer, alles gezählt, auch wenn nicht alles gegessen wird.","note":"Schätzung pro Portion. Rohes Fleisch verliert beim Garen Gewicht und der Saft aus der Form wird nicht separat gezählt, daher kann der tatsächliche Verzehr abweichen."},"seo":{"title":"Rinderbraten aus dem Ofen mit Kartoffeln und Karotten | Manual de Cocina","description":"Rinderbraten aus dem Ofen: ganzes Stück angebraten, mit Knoblauch und Kräutern gewürzt und auf Kartoffeln und Karotten gegart. 6 Portionen. Mit Fotos.","image_variants":["/recetas/asado-de-res-al-horno/portada-1x1.webp","/recetas/asado-de-res-al-horno/portada-4x3.webp","/recetas/asado-de-res-al-horno/portada-16x9.webp"],"faq":[{"q":"Wie lange muss der Braten in den Ofen?","a":"Ein Stück von 1,2 kg braucht bei 180 °C 60 bis 70 Minuten für Medium. Am zuverlässigsten ist die Kerntemperatur: 58 °C vor dem Ruhen."},{"q":"Warum muss der Braten ruhen?","a":"Beim Ruhen verteilt sich der Fleischsaft im Stück. Wird er sofort aufgeschnitten, läuft der Saft aus und das Fleisch wird trockener."},{"q":"Welches Rindfleischstück eignet sich?","a":"Hüfte oder Schwanzstück eignen sich gut, weil sie mager sind und sich in Scheiben schneiden lassen. Auch Filet funktioniert, ist aber zarter und teurer."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"f99c2da1-14a4-5b05-bde6-8522040566ad","recipe_group_id":"2b7dedcb-61b3-4b53-9373-d430aeca9dd5","language":"en","slug":"oven-roasted-beef-with-vegetables","public_path":"/en/oven-roasted-beef-with-vegetables","source_url":null,"title":"Oven-Roasted Beef with Potatoes and Carrots","excerpt":"Oven-roasted beef with potatoes and carrots: a whole cut, seared, seasoned with garlic and herbs, roasted over the vegetables and sliced. Serves 6.","summary":"This oven-roasted beef is made with a whole piece of rump or sirloin, tied and rubbed with garlic, rosemary, thyme, salt and pepper. It is seared in a skillet to brown it and roasted in the oven over a bed of potatoes, carrots and onion, which cook in the meat juices.\n\nIt takes 20 minutes of prep, 30 of tempering, 80 of cooking and 15 of resting. It serves 6.","category":"Main dishes","difficulty":"Medium","course":"Main course","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":80,"total_time_minutes":145,"servings":6,"keywords":["oven-roasted beef","roast beef recipe","roast beef with potatoes and carrots","how to roast beef in the oven","beef roast with vegetables","rump roast in the oven","one-pan beef roast"],"ingredients":[{"name":"whole beef roast (rump or sirloin), tied","amount":"1200","unit":"g","group":"For the beef"},{"name":"garlic cloves","amount":"4","unit":"","group":"For the beef"},{"name":"sprigs of rosemary","amount":"2","unit":"","group":"For the beef"},{"name":"sprigs of thyme","amount":"4","unit":"","group":"For the beef"},{"name":"salt","amount":"1 1/2","unit":"teaspoon","group":"For the beef"},{"name":"black pepper","amount":"1","unit":"teaspoon","group":"For the beef"},{"name":"olive oil","amount":"1","unit":"tablespoon","group":"For the beef"},{"name":"potatoes","amount":"800","unit":"g","group":"For the vegetables"},{"name":"carrots","amount":"400","unit":"g","group":"For the vegetables"},{"name":"onions","amount":"2","unit":"","group":"For the vegetables"},{"name":"olive oil","amount":"2","unit":"tablespoon","group":"For the vegetables"},{"name":"salt","amount":"1/2","unit":"teaspoon","group":"For the vegetables"}],"steps":[{"title":"Prepare the ingredients","content":"Have ready 1.2 kg of beef in one piece (rump or sirloin) tied with kitchen twine, 800 g potatoes, 400 g carrots, 2 onions, 4 garlic cloves, rosemary, thyme, olive oil, salt and pepper. Take the beef out of the fridge and preheat the oven to 180 °C.","image_url":"/recetas/asado-de-res-al-horno/paso-01.webp","image_alt":"Oven-Roasted Beef with Potatoes and Carrots: Prepare the ingredients"},{"title":"Season the beef","content":"Pat the roast dry with paper towels. Mix 1½ teaspoons salt, 1 teaspoon pepper, 4 chopped garlic cloves and the chopped leaves of 2 sprigs of rosemary and 4 of thyme, and rub it all over the beef. Leave it for 30 minutes at room temperature.","image_url":"/recetas/asado-de-res-al-horno/paso-02.webp","image_alt":"Oven-Roasted Beef with Potatoes and Carrots: Season the beef"},{"title":"Sear the beef","content":"Heat 1 tablespoon oil in a cast-iron skillet over high heat. Sear the roast for 2 to 3 minutes on each side, including the ends, until browned all over, about 10 minutes in total.","image_url":"/recetas/asado-de-res-al-horno/paso-03.webp","image_alt":"Oven-Roasted Beef with Potatoes and Carrots: Sear the beef"},{"title":"Prepare the vegetables","content":"Cut 800 g potatoes and 400 g carrots into 4 cm pieces and the 2 onions into wedges. Toss them in a baking dish with 2 tablespoons oil and ½ teaspoon salt. Set the seared beef in the center, on top of the vegetables.","image_url":"/recetas/asado-de-res-al-horno/paso-04.webp","image_alt":"Oven-Roasted Beef with Potatoes and Carrots: Prepare the vegetables"},{"title":"Roast the beef","content":"Roast at 180 °C on the middle rack for 60 to 70 minutes. Halfway through, stir the vegetables so they brown evenly.","image_url":"/recetas/asado-de-res-al-horno/paso-05.webp","image_alt":"Oven-Roasted Beef with Potatoes and Carrots: Roast the beef"},{"title":"Check the temperature","content":"Insert a meat thermometer into the center of the beef. Take it out at 58 °C for medium, because it rises to about 63 °C as it rests. If it has not reached that, roast for 10 more minutes and check again.","image_url":"/recetas/asado-de-res-al-horno/paso-06.webp","image_alt":"Oven-Roasted Beef with Potatoes and Carrots: Check the temperature"},{"title":"Let the beef rest","content":"Move the beef to a board, tent it loosely with aluminum foil and let it rest for 15 minutes so it does not lose its juices when sliced. Leave the vegetables in the dish.","image_url":"/recetas/asado-de-res-al-horno/paso-07.webp","image_alt":"Oven-Roasted Beef with Potatoes and Carrots: Let the beef rest"},{"title":"Slice and serve","content":"Remove the twine and slice the beef 1 cm thick, against the grain. Serve hot with the potatoes, carrots and the juices left in the dish.","image_url":"/recetas/asado-de-res-al-horno/paso-08.webp","image_alt":"Oven-Roasted Beef with Potatoes and Carrots: Slice and serve"}],"image_url":"/recetas/asado-de-res-al-horno/portada.webp","gallery":[{"url":"/recetas/asado-de-res-al-horno/portada.webp","alt":"Oven-Roasted Beef with Potatoes and Carrots"}],"notes":"Always slice against the grain: it makes the beef more tender. The time depends on the thickness of the roast and your oven, so a thermometer is worth using. As a guide, 58 °C gives a pink medium and 65 °C or more a more well-done roast. For a thicker or heavier piece, roast longer. You can spoon the juices from the dish over the slices when serving. Leftovers keep for 3 days in the fridge, well covered; reheat with a little water or broth so they do not dry out.","nutrition":{"calories":570,"protein_g":44.6,"carbs_g":33,"fat_g":28.6,"sodium_mg":942,"serving_size":"1 serving (about 150 g beef and 200 g vegetables)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 6 servings: 1,200 g raw beef (approximated with indicative values for rump, with no FDC id; all of it is counted even though some fat and juices stay in the dish), 800 g potato, 400 g carrot, 300 g onion, 12 g garlic, 3 g rosemary, 3 g thyme, 40.5 g olive oil, 12 g salt and 2.3 g pepper, all counted even if not fully eaten.","note":"Estimate per serving. Raw beef loses weight as it roasts and the juices in the dish are not counted separately, so actual intake may vary."},"seo":{"title":"Oven-Roasted Beef with Potatoes and Carrots | Manual de Cocina","description":"Oven-roasted beef: a whole cut seared, seasoned with garlic and herbs and roasted over potatoes and carrots. Serves 6. Step by step with photos.","image_variants":["/recetas/asado-de-res-al-horno/portada-1x1.webp","/recetas/asado-de-res-al-horno/portada-4x3.webp","/recetas/asado-de-res-al-horno/portada-16x9.webp"],"faq":[{"q":"How long do you roast beef in the oven?","a":"A 1.2 kg roast takes 60 to 70 minutes at 180 °C for medium. The most reliable way is to measure the center: 58 °C before resting."},{"q":"Why does a roast need to rest?","a":"While it rests, the juices redistribute through the meat. If you slice it right away, they run out and the beef is drier."},{"q":"Which cut of beef should I use?","a":"Rump or sirloin work well because they are lean and slice neatly. Tenderloin also works, but it is more tender and more expensive."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"06f08a75-6302-5dca-aa31-3c1c270f144d","recipe_group_id":"2b7dedcb-61b3-4b53-9373-d430aeca9dd5","language":"fr","slug":"roti-de-boeuf-au-four","public_path":"/fr/roti-de-boeuf-au-four","source_url":null,"title":"Rôti de bœuf au four aux pommes de terre et carottes","excerpt":"Rôti de bœuf au four aux pommes de terre et carottes : une pièce entière saisie, assaisonnée à l'ail et aux herbes, rôtie sur les légumes et tranchée. Pour 6 portions.","summary":"Ce rôti de bœuf au four se prépare avec une pièce entière de rumsteck ou de tende de tranche, ficelée et frottée d'ail, de romarin, de thym, de sel et de poivre. Elle est saisie à la poêle pour la dorer, puis rôtie au four sur un lit de pommes de terre, de carottes et d'oignons qui cuisent dans le jus de la viande.\n\nIl demande 20 minutes de préparation, 30 de mise à température, 80 de cuisson et 15 de repos. Pour 6 portions.","category":"Plats principaux","difficulty":"Moyenne","course":"Plat principal","cuisine":"Internationale","prep_time_minutes":20,"cook_time_minutes":80,"total_time_minutes":145,"servings":6,"keywords":["rôti de bœuf au four","recette rôti de bœuf","rôti de bœuf aux pommes de terre et carottes","comment cuire un rôti de bœuf au four","rôti de bœuf et légumes","rumsteck au four","rôti de viande aux légumes"],"ingredients":[{"name":"rôti de bœuf (rumsteck ou tende de tranche), ficelé","amount":"1200","unit":"g","group":"Pour la viande"},{"name":"gousses d'ail","amount":"4","unit":"","group":"Pour la viande"},{"name":"brins de romarin","amount":"2","unit":"","group":"Pour la viande"},{"name":"brins de thym","amount":"4","unit":"","group":"Pour la viande"},{"name":"sel","amount":"1 1/2","unit":"cuillère à café","group":"Pour la viande"},{"name":"poivre noir","amount":"1","unit":"cuillère à café","group":"Pour la viande"},{"name":"huile d'olive","amount":"1","unit":"cuillère à soupe","group":"Pour la viande"},{"name":"pommes de terre","amount":"800","unit":"g","group":"Pour les légumes"},{"name":"carottes","amount":"400","unit":"g","group":"Pour les légumes"},{"name":"oignons","amount":"2","unit":"","group":"Pour les légumes"},{"name":"huile d'olive","amount":"2","unit":"cuillère à soupe","group":"Pour les légumes"},{"name":"sel","amount":"1/2","unit":"cuillère à café","group":"Pour les légumes"}],"steps":[{"title":"Préparer les ingrédients","content":"Prévoir 1,2 kg de bœuf en une seule pièce (rumsteck ou tende de tranche) ficelée, 800 g de pommes de terre, 400 g de carottes, 2 oignons, 4 gousses d'ail, du romarin, du thym, de l'huile d'olive, du sel et du poivre. Sortir la viande du réfrigérateur et préchauffer le four à 180 °C.","image_url":"/recetas/asado-de-res-al-horno/paso-01.webp","image_alt":"Rôti de bœuf au four aux pommes de terre et carottes: Préparer les ingrédients"},{"title":"Assaisonner la viande","content":"Éponger le rôti avec du papier absorbant. Mélanger 1 ½ cuillère à café de sel, 1 cuillère à café de poivre, 4 gousses d'ail hachées et les feuilles hachées de 2 brins de romarin et de 4 de thym, et frotter toute la viande. La laisser 30 minutes à température ambiante.","image_url":"/recetas/asado-de-res-al-horno/paso-02.webp","image_alt":"Rôti de bœuf au four aux pommes de terre et carottes: Assaisonner la viande"},{"title":"Saisir la viande","content":"Chauffer 1 cuillère à soupe d'huile dans une poêle en fonte à feu vif. Saisir le rôti 2 à 3 minutes sur chaque face, y compris les extrémités, jusqu'à ce qu'il soit doré de partout, environ 10 minutes en tout.","image_url":"/recetas/asado-de-res-al-horno/paso-03.webp","image_alt":"Rôti de bœuf au four aux pommes de terre et carottes: Saisir la viande"},{"title":"Préparer les légumes","content":"Couper 800 g de pommes de terre et 400 g de carottes en morceaux de 4 cm et les 2 oignons en quartiers. Les mélanger dans un plat à four avec 2 cuillères à soupe d'huile et ½ cuillère à café de sel. Poser la viande saisie au centre, sur les légumes.","image_url":"/recetas/asado-de-res-al-horno/paso-04.webp","image_alt":"Rôti de bœuf au four aux pommes de terre et carottes: Préparer les légumes"},{"title":"Rôtir au four","content":"Cuire à 180 °C, sur la grille du milieu, de 60 à 70 minutes. À mi-cuisson, remuer les légumes pour qu'ils dorent de façon uniforme.","image_url":"/recetas/asado-de-res-al-horno/paso-05.webp","image_alt":"Rôti de bœuf au four aux pommes de terre et carottes: Rôtir au four"},{"title":"Vérifier la température","content":"Planter un thermomètre à viande au centre du rôti. Le sortir du four à 58 °C pour une cuisson à point, car la température monte à environ 63 °C pendant le repos. Si elle n'est pas atteinte, cuire 10 minutes de plus et mesurer à nouveau.","image_url":"/recetas/asado-de-res-al-horno/paso-06.webp","image_alt":"Rôti de bœuf au four aux pommes de terre et carottes: Vérifier la température"},{"title":"Laisser reposer la viande","content":"Poser la viande sur une planche, la couvrir sans serrer de papier d'aluminium et la laisser reposer 15 minutes pour qu'elle ne perde pas son jus à la découpe. Laisser les légumes dans le plat.","image_url":"/recetas/asado-de-res-al-horno/paso-07.webp","image_alt":"Rôti de bœuf au four aux pommes de terre et carottes: Laisser reposer la viande"},{"title":"Trancher et servir","content":"Retirer la ficelle et trancher la viande en tranches de 1 cm, en travers des fibres. Servir chaud avec les pommes de terre, les carottes et le jus resté dans le plat.","image_url":"/recetas/asado-de-res-al-horno/paso-08.webp","image_alt":"Rôti de bœuf au four aux pommes de terre et carottes: Trancher et servir"}],"image_url":"/recetas/asado-de-res-al-horno/portada.webp","gallery":[{"url":"/recetas/asado-de-res-al-horno/portada.webp","alt":"Rôti de bœuf au four aux pommes de terre et carottes"}],"notes":"Toujours trancher en travers des fibres : la viande est plus tendre. Le temps dépend de l'épaisseur de la pièce et du four ; un thermomètre est donc utile. À titre indicatif, 58 °C donne une cuisson à point rosée et 65 °C ou plus une cuisson plus avancée. Pour une pièce plus épaisse ou plus lourde, prolonger la cuisson. On peut arroser les tranches avec le jus du plat au moment de servir. Les restes se conservent 3 jours au réfrigérateur, bien couverts ; les réchauffer avec un peu d'eau ou de bouillon pour qu'ils ne se dessèchent pas.","nutrition":{"calories":570,"protein_g":44.6,"carbs_g":33,"fat_g":28.6,"sodium_mg":942,"serving_size":"1 portion (environ 150 g de viande et 200 g de légumes)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 6 portions : 1 200 g de bœuf cru (approché avec des valeurs indicatives de rumsteck, sans identifiant FDC ; tout est compté même si une partie du gras et du jus reste dans le plat), 800 g de pommes de terre, 400 g de carottes, 300 g d'oignons, 12 g d'ail, 3 g de romarin, 3 g de thym, 40,5 g d'huile d'olive, 12 g de sel et 2,3 g de poivre, le tout compté même s'il n'est pas entièrement consommé.","note":"Estimation par portion. La viande crue perd du poids à la cuisson et le jus du plat n'est pas compté à part ; la consommation réelle peut donc varier."},"seo":{"title":"Rôti de bœuf au four aux pommes de terre et carottes | Manual de Cocina","description":"Rôti de bœuf au four : pièce entière saisie, assaisonnée à l'ail et aux herbes, rôtie sur des pommes de terre et des carottes. Pour 6 portions. En photos.","image_variants":["/recetas/asado-de-res-al-horno/portada-1x1.webp","/recetas/asado-de-res-al-horno/portada-4x3.webp","/recetas/asado-de-res-al-horno/portada-16x9.webp"],"faq":[{"q":"Combien de temps faut-il cuire un rôti de bœuf au four ?","a":"Une pièce de 1,2 kg demande 60 à 70 minutes à 180 °C pour une cuisson à point. Le plus fiable est de mesurer le centre : 58 °C avant le repos."},{"q":"Pourquoi faut-il laisser reposer le rôti ?","a":"Pendant le repos, le jus se répartit dans la pièce. Si on la tranche tout de suite, il s'échappe et la viande est plus sèche."},{"q":"Quel morceau de bœuf choisir ?","a":"Le rumsteck ou la tende de tranche conviennent bien, car ils sont maigres et se tranchent proprement. Le filet fonctionne aussi, mais il est plus tendre et plus cher."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"a4f591f6-690e-56d8-b9d5-728e8e11bed5","recipe_group_id":"2b7dedcb-61b3-4b53-9373-d430aeca9dd5","language":"it","slug":"arrosto-di-manzo-al-forno","public_path":"/it/arrosto-di-manzo-al-forno","source_url":null,"title":"Arrosto di manzo al forno con patate e carote","excerpt":"Arrosto di manzo al forno con patate e carote: un pezzo intero rosolato, condito con aglio ed erbe, cotto sulle verdure e affettato. Per 6 porzioni.","summary":"Questo arrosto di manzo al forno si prepara con un pezzo intero di scamone o girello, legato e strofinato con aglio, rosmarino, timo, sale e pepe. Si rosola in padella per dorarlo e si cuoce in forno su un letto di patate, carote e cipolla, che cuociono nei succhi della carne.\n\nRichiede 20 minuti di preparazione, 30 per portarlo a temperatura ambiente, 80 di cottura e 15 di riposo. Per 6 porzioni.","category":"Secondi piatti","difficulty":"Media","course":"Piatto principale","cuisine":"Internazionale","prep_time_minutes":20,"cook_time_minutes":80,"total_time_minutes":145,"servings":6,"keywords":["arrosto di manzo al forno","ricetta arrosto di manzo","arrosto di manzo con patate e carote","come cuocere l'arrosto di manzo al forno","arrosto con verdure al forno","scamone al forno","carne al forno con verdure"],"ingredients":[{"name":"arrosto di manzo (scamone o girello), legato","amount":"1200","unit":"g","group":"Per la carne"},{"name":"spicchi d'aglio","amount":"4","unit":"","group":"Per la carne"},{"name":"rametti di rosmarino","amount":"2","unit":"","group":"Per la carne"},{"name":"rametti di timo","amount":"4","unit":"","group":"Per la carne"},{"name":"sale","amount":"1 1/2","unit":"cucchiaino","group":"Per la carne"},{"name":"pepe nero","amount":"1","unit":"cucchiaino","group":"Per la carne"},{"name":"olio d'oliva","amount":"1","unit":"cucchiaio","group":"Per la carne"},{"name":"patate","amount":"800","unit":"g","group":"Per le verdure"},{"name":"carote","amount":"400","unit":"g","group":"Per le verdure"},{"name":"cipolle","amount":"2","unit":"","group":"Per le verdure"},{"name":"olio d'oliva","amount":"2","unit":"cucchiaio","group":"Per le verdure"},{"name":"sale","amount":"1/2","unit":"cucchiaino","group":"Per le verdure"}],"steps":[{"title":"Prepara gli ingredienti","content":"Tieni pronti 1,2 kg di manzo in un unico pezzo (scamone o girello) legato con spago da cucina, 800 g di patate, 400 g di carote, 2 cipolle, 4 spicchi d'aglio, rosmarino, timo, olio d'oliva, sale e pepe. Togli la carne dal frigorifero e preriscalda il forno a 180 °C.","image_url":"/recetas/asado-de-res-al-horno/paso-01.webp","image_alt":"Arrosto di manzo al forno con patate e carote: Prepara gli ingredienti"},{"title":"Condisci la carne","content":"Asciuga l'arrosto con carta da cucina. Mescola 1 cucchiaino e ½ di sale, 1 cucchiaino di pepe, 4 spicchi d'aglio tritati e le foglie tritate di 2 rametti di rosmarino e 4 di timo, e strofina tutta la carne. Lasciala 30 minuti a temperatura ambiente.","image_url":"/recetas/asado-de-res-al-horno/paso-02.webp","image_alt":"Arrosto di manzo al forno con patate e carote: Condisci la carne"},{"title":"Rosola la carne","content":"Scalda 1 cucchiaio di olio in una padella di ghisa a fuoco vivo. Rosola l'arrosto 2-3 minuti per lato, comprese le estremità, finché è dorato ovunque, circa 10 minuti in tutto.","image_url":"/recetas/asado-de-res-al-horno/paso-03.webp","image_alt":"Arrosto di manzo al forno con patate e carote: Rosola la carne"},{"title":"Prepara le verdure","content":"Taglia 800 g di patate e 400 g di carote in pezzi da 4 cm e le 2 cipolle a spicchi. Mescolale in una teglia con 2 cucchiai di olio e ½ cucchiaino di sale. Appoggia la carne rosolata al centro, sopra le verdure.","image_url":"/recetas/asado-de-res-al-horno/paso-04.webp","image_alt":"Arrosto di manzo al forno con patate e carote: Prepara le verdure"},{"title":"Inforna l'arrosto","content":"Cuoci a 180 °C, sul ripiano centrale, per 60-70 minuti. A metà cottura mescola le verdure perché si dorino in modo uniforme.","image_url":"/recetas/asado-de-res-al-horno/paso-05.webp","image_alt":"Arrosto di manzo al forno con patate e carote: Inforna l'arrosto"},{"title":"Controlla la temperatura","content":"Infila un termometro da cucina al centro della carne. Toglila dal forno a 58 °C per una cottura media, perché sale a circa 63 °C durante il riposo. Se non ci è arrivata, cuoci altri 10 minuti e misura di nuovo.","image_url":"/recetas/asado-de-res-al-horno/paso-06.webp","image_alt":"Arrosto di manzo al forno con patate e carote: Controlla la temperatura"},{"title":"Lascia riposare la carne","content":"Trasferisci la carne su un tagliere, coprila senza stringere con carta stagnola e lasciala riposare 15 minuti perché non perda i succhi quando la tagli. Lascia le verdure nella teglia.","image_url":"/recetas/asado-de-res-al-horno/paso-07.webp","image_alt":"Arrosto di manzo al forno con patate e carote: Lascia riposare la carne"},{"title":"Affetta e servi","content":"Rimuovi lo spago e affetta la carne a fette di 1 cm, contro la fibra. Servila calda con le patate, le carote e i succhi rimasti nella teglia.","image_url":"/recetas/asado-de-res-al-horno/paso-08.webp","image_alt":"Arrosto di manzo al forno con patate e carote: Affetta e servi"}],"image_url":"/recetas/asado-de-res-al-horno/portada.webp","gallery":[{"url":"/recetas/asado-de-res-al-horno/portada.webp","alt":"Arrosto di manzo al forno con patate e carote"}],"notes":"Affetta sempre contro la fibra: la carne risulta più tenera. Il tempo dipende dallo spessore del pezzo e dal forno, quindi conviene usare un termometro. Come riferimento, 58 °C dà una cottura media rosata e 65 °C o più una cottura più avanzata. Se il pezzo è più spesso o più pesante, allunga la cottura. Puoi versare i succhi della teglia sulle fette al momento di servire. Gli avanzi si conservano 3 giorni in frigorifero, ben coperti; riscaldali con un po' d'acqua o brodo perché non si secchino.","nutrition":{"calories":570,"protein_g":44.6,"carbs_g":33,"fat_g":28.6,"sodium_mg":942,"serving_size":"1 porzione (circa 150 g di carne e 200 g di verdure)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 6 porzioni: 1.200 g di manzo crudo (approssimato con valori indicativi di scamone, senza id FDC; si conta tutto anche se parte del grasso e dei succhi resta nella teglia), 800 g di patate, 400 g di carote, 300 g di cipolla, 12 g di aglio, 3 g di rosmarino, 3 g di timo, 40,5 g di olio d'oliva, 12 g di sale e 2,3 g di pepe, tutto contato anche se non viene consumato per intero.","note":"Stima per porzione. La carne cruda perde peso in cottura e i succhi della teglia non sono contati a parte, quindi il consumo reale può variare."},"seo":{"title":"Arrosto di manzo al forno con patate e carote | Manual de Cocina","description":"Arrosto di manzo al forno: pezzo intero rosolato, condito con aglio ed erbe e cotto su patate e carote. Per 6 porzioni. Passo dopo passo con foto.","image_variants":["/recetas/asado-de-res-al-horno/portada-1x1.webp","/recetas/asado-de-res-al-horno/portada-4x3.webp","/recetas/asado-de-res-al-horno/portada-16x9.webp"],"faq":[{"q":"Quanto tempo si cuoce l'arrosto di manzo al forno?","a":"Un pezzo da 1,2 kg richiede 60-70 minuti a 180 °C per una cottura media. Il metodo più affidabile è misurare il centro: 58 °C prima del riposo."},{"q":"Perché l'arrosto deve riposare?","a":"Durante il riposo i succhi si distribuiscono nel pezzo. Se lo affetti subito, escono e la carne è più asciutta."},{"q":"Quale taglio di manzo si usa?","a":"Scamone o girello funzionano bene perché sono magri e si affettano in modo netto. Va bene anche il filetto, che però è più tenero e più caro."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"51154735-9436-5d62-82f3-8372fcb94e5b","recipe_group_id":"2b7dedcb-61b3-4b53-9373-d430aeca9dd5","language":"ja","slug":"牛肉のオーブンロースト","public_path":"/ja/牛肉のオーブンロースト","source_url":null,"title":"牛肉のオーブンロースト（じゃがいも・にんじん添え）","excerpt":"かたまり肉を焼き色をつけ、にんにくとハーブで味つけして、じゃがいもとにんじんの上でオーブンで焼いた牛肉料理。薄く切って食べます。6人分です。","summary":"このオーブンローストは、牛もも肉（ランプやしんたまなど）のかたまりをたこ糸で縛り、にんにく、ローズマリー、タイム、塩、こしょうをすり込んで作ります。フライパンで焼き色をつけたあと、じゃがいも、にんじん、玉ねぎの上にのせてオーブンで焼くと、野菜が肉汁を吸っておいしく焼けます。\n\n下ごしらえ20分、常温にもどす時間30分、加熱80分、休ませる時間15分です。6人分です。","category":"主菜","difficulty":"普通","course":"メインディッシュ","cuisine":"インターナショナル","prep_time_minutes":20,"cook_time_minutes":80,"total_time_minutes":145,"servings":6,"keywords":["牛肉 オーブンロースト","ローストビーフ 作り方 オーブン","牛かたまり肉 オーブン 野菜","かたまり肉 オーブン焼き","牛肉 じゃがいも にんじん オーブン","ランプ肉 オーブン","オーブン 肉料理 野菜付き"],"ingredients":[{"name":"牛もも肉のかたまり（ランプまたはしんたま）、たこ糸で縛ったもの","amount":"1200","unit":"g","group":"肉用"},{"name":"にんにく","amount":"4","unit":"","group":"肉用"},{"name":"ローズマリー（枝）","amount":"2","unit":"","group":"肉用"},{"name":"タイム（枝）","amount":"4","unit":"","group":"肉用"},{"name":"塩","amount":"1 1/2","unit":"小さじ","group":"肉用"},{"name":"黒こしょう","amount":"1","unit":"小さじ","group":"肉用"},{"name":"オリーブオイル","amount":"1","unit":"大さじ","group":"肉用"},{"name":"じゃがいも","amount":"800","unit":"g","group":"野菜用"},{"name":"にんじん","amount":"400","unit":"g","group":"野菜用"},{"name":"玉ねぎ","amount":"2","unit":"","group":"野菜用"},{"name":"オリーブオイル","amount":"2","unit":"大さじ","group":"野菜用"},{"name":"塩","amount":"1/2","unit":"小さじ","group":"野菜用"}],"steps":[{"title":"材料を準備する","content":"牛もも肉のかたまり1.2kg（ランプまたはしんたま、たこ糸で縛ったもの）、じゃがいも800g、にんじん400g、玉ねぎ2個、にんにく4片、ローズマリー、タイム、オリーブオイル、塩、こしょうを用意します。肉を冷蔵庫から出し、オーブンを180°Cに予熱します。","image_url":"/recetas/asado-de-res-al-horno/paso-01.webp","image_alt":"牛肉のオーブンロースト（じゃがいも・にんじん添え）: 材料を準備する"},{"title":"肉に味をつける","content":"肉の水気をキッチンペーパーでふきます。塩小さじ1½、こしょう小さじ1、みじん切りにしたにんにく4片、ローズマリー2枝とタイム4枝の葉のみじん切りを混ぜ、肉全体にすり込みます。常温で30分おきます。","image_url":"/recetas/asado-de-res-al-horno/paso-02.webp","image_alt":"牛肉のオーブンロースト（じゃがいも・にんじん添え）: 肉に味をつける"},{"title":"肉に焼き色をつける","content":"鋳鉄のフライパンにオリーブオイル大さじ1を入れて強火で熱します。肉の両端も含めて各面を2〜3分ずつ、全体にこんがり焼き色がつくまで、合計10分ほど焼きます。","image_url":"/recetas/asado-de-res-al-horno/paso-03.webp","image_alt":"牛肉のオーブンロースト（じゃがいも・にんじん添え）: 肉に焼き色をつける"},{"title":"野菜を準備する","content":"じゃがいも800gとにんじん400gを4cm角に切り、玉ねぎ2個はくし形に切ります。耐熱皿に入れ、オリーブオイル大さじ2と塩小さじ½を加えて混ぜます。焼き色をつけた肉を、野菜の上の中央にのせます。","image_url":"/recetas/asado-de-res-al-horno/paso-04.webp","image_alt":"牛肉のオーブンロースト（じゃがいも・にんじん添え）: 野菜を準備する"},{"title":"オーブンで焼く","content":"180°Cのオーブンの中段で60〜70分焼きます。半分の時間がたったら、野菜を混ぜて均一に焼き色をつけます。","image_url":"/recetas/asado-de-res-al-horno/paso-05.webp","image_alt":"牛肉のオーブンロースト（じゃがいも・にんじん添え）: オーブンで焼く"},{"title":"温度を確かめる","content":"肉の中心に肉用温度計を刺します。ミディアムなら58°Cで取り出します。休ませるあいだに約63°Cまで上がります。届いていなければ、10分追加で焼いて再び測ります。","image_url":"/recetas/asado-de-res-al-horno/paso-06.webp","image_alt":"牛肉のオーブンロースト（じゃがいも・にんじん添え）: 温度を確かめる"},{"title":"肉を休ませる","content":"肉をまな板に移し、アルミホイルをふんわりかぶせて15分休ませます。切るときに肉汁が出ないようにするためです。野菜は耐熱皿に残しておきます。","image_url":"/recetas/asado-de-res-al-horno/paso-07.webp","image_alt":"牛肉のオーブンロースト（じゃがいも・にんじん添え）: 肉を休ませる"},{"title":"切り分けて盛りつける","content":"たこ糸を外し、肉を繊維に対して垂直に厚さ1cmに切ります。じゃがいも、にんじん、耐熱皿に残った肉汁とともに、温かいうちに盛りつけます。","image_url":"/recetas/asado-de-res-al-horno/paso-08.webp","image_alt":"牛肉のオーブンロースト（じゃがいも・にんじん添え）: 切り分けて盛りつける"}],"image_url":"/recetas/asado-de-res-al-horno/portada.webp","gallery":[{"url":"/recetas/asado-de-res-al-horno/portada.webp","alt":"牛肉のオーブンロースト（じゃがいも・にんじん添え）"}],"notes":"肉は必ず繊維に対して垂直に切ると、やわらかくなります。焼き時間は肉の厚みとオーブンによって変わるので、温度計を使うと安心です。目安として、58°Cでピンク色のミディアム、65°C以上でしっかり火が通ります。肉が厚い、または重いときは、焼き時間を延ばします。皿に残った肉汁は、盛りつけるときにスライスにかけられます。残りは、しっかりふたをして冷蔵庫で3日保存でき、少量の水かスープを加えて温め直すとパサつきません。","nutrition":{"calories":570,"protein_g":44.6,"carbs_g":33,"fat_g":28.6,"sodium_mg":942,"serving_size":"1人分（肉約150gと野菜約200g）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、6人分で割って合計しています。生の牛肉1,200g（ランプの目安の値で近似、FDC番号なし。脂や肉汁の一部が皿に残りますが全量を計算）、じゃがいも800g、にんじん400g、玉ねぎ300g、にんにく12g、ローズマリー3g、タイム3g、オリーブオイル40.5g、塩12g、こしょう2.3gを使用しています。すべて全量を計算しています。","note":"1人分の目安です。生の肉は焼くと重さが減り、皿の肉汁は別に計算していないため、実際の摂取量は変わることがあります。"},"seo":{"title":"牛肉のオーブンロースト｜じゃがいも・にんじん添えの作り方 | Manual de Cocina","description":"かたまり肉に焼き色をつけ、にんにくとハーブで味つけして、じゃがいもとにんじんの上でオーブンで焼く牛肉料理。6人分。作り方を写真付きで解説します。","image_variants":["/recetas/asado-de-res-al-horno/portada-1x1.webp","/recetas/asado-de-res-al-horno/portada-4x3.webp","/recetas/asado-de-res-al-horno/portada-16x9.webp"],"faq":[{"q":"牛肉のかたまりはオーブンで何分焼きますか？","a":"1.2kgのかたまりなら、180°Cでミディアムに60〜70分が目安です。いちばん確実なのは中心の温度を測ることで、休ませる前に58°Cです。"},{"q":"なぜ焼いたあと休ませるのですか？","a":"休ませるあいだに肉汁が全体に行き渡ります。すぐに切ると肉汁が流れ出て、肉がパサつきます。"},{"q":"どの部位の牛肉を使いますか？","a":"脂が少なく薄切りにしやすいランプやしんたまが向いています。ヒレ肉でも作れますが、よりやわらかく、価格も高めです。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"211dafca-f8bd-5d57-bc8a-bc237e2c8763","recipe_group_id":"2b7dedcb-61b3-4b53-9373-d430aeca9dd5","language":"pt","slug":"assado-de-carne-no-forno","public_path":"/pt/assado-de-carne-no-forno","source_url":null,"title":"Assado de carne no forno com batatas e cenouras","excerpt":"Assado de carne no forno com batatas e cenouras: uma peça inteira selada, temperada com alho e ervas, assada sobre os legumes e fatiada. Rende 6 porções.","summary":"Este assado de carne no forno é feito com uma peça inteira de alcatra ou coxão duro, amarrada e esfregada com alho, alecrim, tomilho, sal e pimenta. Ela é selada na frigideira para dourar e assada no forno sobre uma cama de batatas, cenouras e cebola, que cozinham no caldo da carne.\n\nLeva 20 minutos de preparo, 30 para chegar à temperatura ambiente, 80 de forno e 15 de descanso. Rende 6 porções.","category":"Pratos principais","difficulty":"Média","course":"Prato principal","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":80,"total_time_minutes":145,"servings":6,"keywords":["assado de carne no forno","receita de assado de carne","assado de carne com batatas e cenouras","como fazer assado de carne no forno","carne assada com legumes","alcatra no forno","assado de carne com legumes"],"ingredients":[{"name":"peça de carne bovina (alcatra ou coxão duro), amarrada","amount":"1200","unit":"g","group":"Para a carne"},{"name":"dentes de alho","amount":"4","unit":"","group":"Para a carne"},{"name":"ramos de alecrim","amount":"2","unit":"","group":"Para a carne"},{"name":"ramos de tomilho","amount":"4","unit":"","group":"Para a carne"},{"name":"sal","amount":"1 1/2","unit":"colher de chá","group":"Para a carne"},{"name":"pimenta-do-reino","amount":"1","unit":"colher de chá","group":"Para a carne"},{"name":"azeite","amount":"1","unit":"colher de sopa","group":"Para a carne"},{"name":"batatas","amount":"800","unit":"g","group":"Para os legumes"},{"name":"cenouras","amount":"400","unit":"g","group":"Para os legumes"},{"name":"cebolas","amount":"2","unit":"","group":"Para os legumes"},{"name":"azeite","amount":"2","unit":"colher de sopa","group":"Para os legumes"},{"name":"sal","amount":"1/2","unit":"colher de chá","group":"Para os legumes"}],"steps":[{"title":"Separe os ingredientes","content":"Tenha à mão 1,2 kg de carne bovina em uma peça (alcatra ou coxão duro) amarrada com barbante de cozinha, 800 g de batatas, 400 g de cenouras, 2 cebolas, 4 dentes de alho, alecrim, tomilho, azeite, sal e pimenta. Tire a carne da geladeira e preaqueça o forno a 180 °C.","image_url":"/recetas/asado-de-res-al-horno/paso-01.webp","image_alt":"Assado de carne no forno com batatas e cenouras: Separe os ingredientes"},{"title":"Tempere a carne","content":"Seque a peça com papel-toalha. Misture 1 colher de chá e ½ de sal, 1 colher de chá de pimenta, 4 dentes de alho picados e as folhas picadas de 2 ramos de alecrim e 4 de tomilho, e esfregue em toda a carne. Deixe por 30 minutos em temperatura ambiente.","image_url":"/recetas/asado-de-res-al-horno/paso-02.webp","image_alt":"Assado de carne no forno com batatas e cenouras: Tempere a carne"},{"title":"Sele a carne","content":"Aqueça 1 colher de sopa de azeite em uma frigideira de ferro em fogo alto. Sele a peça por 2 a 3 minutos de cada lado, inclusive as pontas, até dourar por inteiro, cerca de 10 minutos no total.","image_url":"/recetas/asado-de-res-al-horno/paso-03.webp","image_alt":"Assado de carne no forno com batatas e cenouras: Sele a carne"},{"title":"Prepare os legumes","content":"Corte 800 g de batata e 400 g de cenoura em pedaços de 4 cm e as 2 cebolas em gomos. Misture em uma assadeira com 2 colheres de sopa de azeite e ½ colher de chá de sal. Coloque a carne selada no centro, sobre os legumes.","image_url":"/recetas/asado-de-res-al-horno/paso-04.webp","image_alt":"Assado de carne no forno com batatas e cenouras: Prepare os legumes"},{"title":"Asse a carne","content":"Asse a 180 °C, na grade do meio, por 60 a 70 minutos. Na metade do tempo, mexa os legumes para dourarem por igual.","image_url":"/recetas/asado-de-res-al-horno/paso-05.webp","image_alt":"Assado de carne no forno com batatas e cenouras: Asse a carne"},{"title":"Confira a temperatura","content":"Espete um termômetro de cozinha no centro da carne. Retire do forno a 58 °C para o ponto médio, porque a temperatura sobe para cerca de 63 °C no descanso. Se ainda não chegou, asse por mais 10 minutos e meça de novo.","image_url":"/recetas/asado-de-res-al-horno/paso-06.webp","image_alt":"Assado de carne no forno com batatas e cenouras: Confira a temperatura"},{"title":"Deixe a carne descansar","content":"Passe a carne para uma tábua, cubra sem apertar com papel-alumínio e deixe descansar por 15 minutos para não soltar os sucos ao cortar. Deixe os legumes na assadeira.","image_url":"/recetas/asado-de-res-al-horno/paso-07.webp","image_alt":"Assado de carne no forno com batatas e cenouras: Deixe a carne descansar"},{"title":"Fatie e sirva","content":"Retire o barbante e fatie a carne em fatias de 1 cm, contra a fibra. Sirva quente com as batatas, as cenouras e o caldo que ficou na assadeira.","image_url":"/recetas/asado-de-res-al-horno/paso-08.webp","image_alt":"Assado de carne no forno com batatas e cenouras: Fatie e sirva"}],"image_url":"/recetas/asado-de-res-al-horno/portada.webp","gallery":[{"url":"/recetas/asado-de-res-al-horno/portada.webp","alt":"Assado de carne no forno com batatas e cenouras"}],"notes":"Fatie sempre contra a fibra: a carne fica mais macia. O tempo depende da espessura da peça e do forno, por isso vale usar um termômetro. Como referência, 58 °C dão um ponto médio rosado, e 65 °C ou mais, um ponto mais passado. Se a peça for mais grossa ou mais pesada, asse por mais tempo. O caldo da assadeira pode ser regado sobre as fatias na hora de servir. As sobras duram 3 dias na geladeira, bem cobertas; reaqueça com um pouco de água ou caldo para não ressecar.","nutrition":{"calories":570,"protein_g":44.6,"carbs_g":33,"fat_g":28.6,"sodium_mg":942,"serving_size":"1 porção (cerca de 150 g de carne e 200 g de legumes)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 6 porções: 1.200 g de carne bovina crua (aproximada com valores indicativos de alcatra, sem código FDC; tudo é contado, mesmo que parte da gordura e do caldo fique na assadeira), 800 g de batata, 400 g de cenoura, 300 g de cebola, 12 g de alho, 3 g de alecrim, 3 g de tomilho, 40,5 g de azeite, 12 g de sal e 2,3 g de pimenta, tudo contado mesmo que não seja consumido por inteiro.","note":"Estimativa por porção. A carne crua perde peso ao assar e o caldo da assadeira não é contado à parte, então o consumo real pode variar."},"seo":{"title":"Assado de carne no forno com batatas e cenouras | Manual de Cocina","description":"Assado de carne no forno: peça inteira selada, temperada com alho e ervas e assada sobre batatas e cenouras. Rende 6 porções. Passo a passo com fotos.","image_variants":["/recetas/asado-de-res-al-horno/portada-1x1.webp","/recetas/asado-de-res-al-horno/portada-4x3.webp","/recetas/asado-de-res-al-horno/portada-16x9.webp"],"faq":[{"q":"Quanto tempo leva para assar a carne no forno?","a":"Uma peça de 1,2 kg leva de 60 a 70 minutos a 180 °C para o ponto médio. O mais confiável é medir o centro: 58 °C antes do descanso."},{"q":"Por que o assado precisa descansar?","a":"No descanso, os sucos se distribuem pela peça. Se for fatiada logo, eles escapam e a carne fica mais seca."},{"q":"Que corte de carne bovina devo usar?","a":"Alcatra ou coxão duro funcionam bem, porque são magros e fatiam com facilidade. O filé também serve, mas é mais macio e mais caro."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/asado-de-res-al-horno') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
